package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;

public class BuildOwner {

    public void service(@Val OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built)
            throws FutureRegistrationDateException {
        Owner owner = ownerMapper.toOwner(request);
        java.time.LocalDate supplied = owner.getRegistrationDate();
        if (supplied != null && supplied.isAfter(java.time.LocalDate.now())) {
            throw new FutureRegistrationDateException(supplied);
        }
        java.time.LocalDate effective = supplied == null
                ? java.time.LocalDate.now() : supplied;
        owner.setRegistrationDate(BusinessDay.roll(effective));
        built.set(owner);
    }
}
=== AddressNormalizer ===
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;

/**
 * Canonical form of an owner address, applied on create and used for every address comparison
 * (household duplicate detection and the shared household id). Whitespace is trimmed and collapsed,
 * the text is upper-cased and common street-type abbreviations are expanded (ST->STREET, RD->ROAD,
 * AVE->AVENUE). A null or all-whitespace address normalizes to {@code ""}.
 */
public final class AddressNormalizer {

    private static final Map<String, String> ABBREVIATIONS =
            Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");

    private AddressNormalizer() {
    }

    public static String normalize(String address) {
        if (address == null || address.isBlank()) {
            return "";
        }
        StringBuilder sb = new StringBuilder();
        for (String word : address.trim().toUpperCase().split("\\s+")) {
            if (sb.length() > 0) {
                sb.append(' ');
            }
            sb.append(ABBREVIATIONS.getOrDefault(word, word));
        }
        return sb.toString();
    }
}

